bounded_host_request.command:
set -euo pipefail
n=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$n")" = true || exit 61
docker exec -i "$n" node --input-type=module - <<'NODE'
import assert from 'node:assert/strict';
import {menuPage} from '/opt/videobot/src/telegram/menuPanel.mjs';
import {createStickerWizard} from '/opt/videobot/src/telegram/stickerWizard.mjs';
import {createCreatorBotUpdateHandler} from '/opt/videobot/src/telegram/creatorBot.mjs';
const menu=menuPage('home');
const buttons=menu.reply_markup.inline_keyboard.flat();
assert(buttons.some(x=>x.callback_data==='menu:listing'));
assert(buttons.some(x=>x.callback_data==='menu:stickers'));
const state=new Map();
state.set(42,{revision:3,screen:'sticker_reconcile',screenMessageId:301,
stickerPending:{status:'needs_reconcile',kind:'regular',nonce:'keep',title:'Existing'}});
const shown=[];
const store={
 read:async id=>state.get(id)||null,
 write:async(id,rev,next)=>{assert.equal(state.get(id)?.revision??0,rev);state.set(id,next);},
 setScreen:async(id,rev,messageId)=>{const cur=state.get(id);assert.equal(cur.revision,rev);state.set(id,{...cur,screenMessageId:messageId});}
};
const api=async()=>true;
const screenTransport={show:async(id,old,panel)=>{shown.push(panel);return {messageId:old||301}}};
const sticker=createStickerWizard({api,sessionStore:store,screenTransport,publishSticker:async()=>{throw Error('NO_LIVE_PUBLISH')}});
const bot=createCreatorBotUpdateHandler({api,sessionStore:store,screenTransport,
 listingStore:{listByOwner:async()=>[],getOwned:async()=>null},
 mediaProcessor:{prepareUserSample:async()=>({fileId:'test',durationSeconds:15})},
 stickerHandler:sticker.handle});
const privateMessage=text=>({message:{chat:{type:'private',id:42},from:{id:42},message_id:401,text}});
const result=await bot(privateMessage('/start'));
assert(result?.handled===true);
assert(shown.length>=1);
assert(shown.at(-1).reply_markup.inline_keyboard.flat().some(x=>x.callback_data==='menu:stickers'));
assert.equal(state.get(42).stickerPending?.nonce,'keep');
const deep=await sticker.handle(privateMessage('/start sticker'));
assert.equal(deep?.handled,true);
assert.equal(state.get(42).screen,'sticker_choose');
assert.equal(state.get(42).stickerPending?.nonce,'keep');
console.log('LIVE_IMAGE_NORMAL_MENU_RENDER=PASS');
console.log('LIVE_IMAGE_STICKER_DEEP_LINK=PASS');
console.log('UNRESOLVED_STICKER_RECEIPT_PRESERVED=PASS');
NODE
docker logs --tail 700 "$n" 2>&1 | grep -q '^CREATOR_DM_POLL_READY=PASS$'
echo CREATEVDOBOT_LIVE_CODE_SMOKE=PASS
